-- Division layer (Phase 2 of the project-permissions model). A `division` is a
-- department (부문/본부) with a single HEAD — the highest-ranked person, auto-
-- derived from the org directory 직급 (anh Luân's call 06-15: "tự suy từ rank
-- cao nhất"). The head gets DEFAULT manage power over EVERY project their
-- division leads (project.lead_division_id) WITHOUT being added to each project,
-- and may assign/change that project's leader. head_email is a COLUMN (one head
-- per division = single source of truth); an admin can re-point it if the org
-- changes. Seed is regenerated by worker/scripts/derive-divisions.mjs.
CREATE TABLE IF NOT EXISTS division (
  id         TEXT PRIMARY KEY,        -- slug, e.g. 'div-architectural-ai-r-and-d-center'
  name       TEXT NOT NULL,           -- English division name from the directory
  head_email TEXT NOT NULL,           -- lower-cased; the division head
  created_at INTEGER,
  updated_at INTEGER
);
CREATE INDEX IF NOT EXISTS ix_division_head ON division(head_email);

-- email → home-division map for every internal user, so a project's leading
-- division can be backfilled from its host and a head/colleague resolved for any
-- member. Seeded from the same directory export.
CREATE TABLE IF NOT EXISTS user_division (
  email       TEXT PRIMARY KEY,       -- lower-cased
  division_id TEXT NOT NULL REFERENCES division(id)
);
CREATE INDEX IF NOT EXISTS ix_user_division ON user_division(division_id);

